argv:
set -euo pipefail
dir=$(mktemp -d)
trap 'rm -rf "$dir"' EXIT
cd "$dir"
cargo +1.99.0 new -q --lib --vcs none consumer
cd consumer
printf 'rayx_reactive = { git = "https://github.com/rayx-ui/RayX.Reactive", tag = "v1.0.0" }\n' >> Cargo.toml
cat > src/lib.rs <<'EOF'
#[cfg(test)]
mod tests {
    use rayx_reactive::prelude::Signal;

    #[test]
    fn uses_the_tagged_release() -> Result<(), Box<dyn std::error::Error>> {
        let count = Signal::new(1);
        count.set(2)?;
        assert_eq!(count.get()?, 2);
        Ok(())
    }
}
EOF
cargo +1.99.0 test
tag=$(git ls-remote --tags https://github.com/rayx-ui/RayX.Reactive | awk '$2 == "refs/tags/v1.0.0^{}" { p = $1 } $2 == "refs/tags/v1.0.0" { t = $1 } END { print (p != "" ? p : t) }')
lock=$(sed -n 's|^source = "git+https://github.com/rayx-ui/RayX.Reactive?tag=v1.0.0#\([0-9a-f]\{40\}\)"$|\1|p' Cargo.lock | head -n 1)
[ -n "$tag" ] && [ "$lock" = "$tag" ] || { echo "Cargo.lock commit '$lock' is not the v1.0.0 commit '$tag'"; exit 1; }
echo "consumer resolved v1.0.0 at $lock"
